import test from 'node:test';import assert from 'node:assert/strict';import {normalizeGazetteer} from '../src/normalizers/gazetteer.js';import {normalizeHudPostalLocation,normalizeHudRelationship} from '../src/normalizers/hud.js';
const base=(source_key:string,record:any):any=>({source_key,release_id:'00000000-0000-0000-0000-000000000001',release_key:'x',ingest_run_id:'00000000-0000-0000-0000-000000000002',artifact_id:'a',ordinal:1,natural_key:'n',record_id:'00000000-0000-0000-0000-000000000003',record,record_sha256:'a'.repeat(64)});
test('state stable identity excludes mutable name',()=>{const x=normalizeGazetteer(base('CENSUS_GAZETTEER_STATE',{GEOID:'51',USPS:'VA',NAME:'Virginia',INTPTLAT:'37.5',INTPTLONG:'-78.8'}));assert.equal(x.canonicalKey,'US:STATE:51');assert.deepEqual(x.identityDocument,{authority:'CENSUS',type:'STATE',geoid:'51'});assert.equal(x.revisionDocument.name,'Virginia')});
test('ZCTA does not require NAME',()=>{const x=normalizeGazetteer(base('CENSUS_GAZETTEER_ZCTA',{GEOID:'22554',GEOIDFQ:'860Z200US22554',INTPTLAT:'38.4',INTPTLONG:'-77.4'}));assert.equal(x.canonicalKey,'US:ZCTA:22554')});
test('HUD zip remains pending USPS authority',()=>{const x=normalizeHudPostalLocation(base('HUD_USPS_ZIP_COUNTY',{zip:'22554'}));assert.equal(x.authorityStatus,'PENDING_EXTERNAL_AUTHORITY');assert.match(String(x.revisionDocument.operational_status),/PENDING_USPS/)});
test('HUD county relationship',()=>{const x=normalizeHudRelationship(base('HUD_USPS_ZIP_COUNTY',{zip:'22554',geoid:'51179',res_ratio:'1',bus_ratio:'1',oth_ratio:'1',tot_ratio:'1'}));assert.equal(x.parentKey,'US:COUNTY:51179');assert.equal(x.relationshipType,'POSTAL_TO_COUNTY')});
test('HUD CBSA relationship',()=>{const x=normalizeHudRelationship(base('HUD_USPS_ZIP_CBSA',{zip:'22554',geoid:'47900',res_ratio:'1',bus_ratio:'1',oth_ratio:'1',tot_ratio:'1'}));assert.equal(x.parentKey,'US:CBSA:47900');assert.equal(x.relationshipType,'POSTAL_TO_CBSA')});
test('HUD ratio above one fails closed',()=>assert.throws(()=>normalizeHudRelationship(base('HUD_USPS_ZIP_COUNTY',{zip:'22554',geoid:'51179',res_ratio:'1.2'})),/INVALID_HUD_RATIO/));

test('HUD CBSA 99999 is not normalized as a CBSA',()=>assert.throws(()=>normalizeHudRelationship(base('HUD_USPS_ZIP_CBSA',{zip:'22554',geoid:'99999',res_ratio:'1',bus_ratio:'1',oth_ratio:'1',tot_ratio:'1'})),/HUD_CBSA_99999_OUTSIDE_CBSA/));
